<form class="panel" method="post"><h2>Thêm chuyển hướng</h2><input type="hidden" name="_token" value="<?=e(csrf())?>"><label>Đường dẫn cũ<input name="source" placeholder="/blog/bai-viet-cu" value="<?=e(old('source',request('source','')))?>" required></label><label>Đường dẫn mới<input name="target" placeholder="/blog/bai-viet-moi" value="<?=e(old('target',''))?>" required></label><label>Loại chuyển hướng<select name="status"><option value="301">301 · vĩnh viễn</option><option value="302">302 · tạm thời</option></select></label><p class="muted">Chỉ chuyển hướng nội bộ. Khi đổi slug của bài/trang/đám cưới, hệ thống tự tạo 301. Không tạo redirect cho đường dẫn đang được nội dung sử dụng.</p><button name="action" value="redirect_save">Lưu chuyển hướng</button></form>
<section class="panel table-wrap"><h2>Chuyển hướng hiện có</h2><table><thead><tr><th>Nguồn</th><th>Đích</th><th>Mã</th><th></th></tr></thead><tbody><?php foreach(\App\Models\SeoRedirect::latest('id')->get() as $r):?><tr><td><?=e($r->source)?><small><?=$r->content_id?'Tự động theo nội dung':'Thủ công'?></small></td><td><?=e($r->target)?></td><td><?=$r->status?></td><td><form method="post" onsubmit="return confirm('Xóa chuyển hướng?')"><input type="hidden" name="_token" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r->id?>"><button class="danger" name="action" value="redirect_delete">Xóa</button></form></td></tr><?php endforeach;?></tbody></table></section>
<section class="panel table-wrap"><h2>URL lỗi 404 gần đây</h2><p class="muted">Lưu tối đa 1.000 đường dẫn, không lưu query, IP hoặc thông tin khách. Chỉ tạo redirect khi có trang thay thế phù hợp.</p><table><thead><tr><th>Đường dẫn</th><th>Lượt</th><th>Lần gần nhất</th><th></th></tr></thead><tbody><?php foreach(\App\Models\SeoNotFound::latest('updated_at')->limit(50)->get() as $r):?><tr><td><?=e($r->path)?></td><td><?=$r->hits?></td><td><?=e($r->updated_at->timezone('Asia/Ho_Chi_Minh')->format('d/m/Y H:i'))?></td><td><a href="<?=e(adminUrl('redirects',['source'=>$r->path]))?>">Tạo redirect ↗</a></td></tr><?php endforeach;?></tbody></table></section>
